#include <algorithm>
#include <cctype>
#include <optional>
#include <string>
#include <vector>

struct LineCol { int line, col; };

class TextDocument
{
public:
    explicit TextDocument(std::string text = "") : m_text{ std::move(text) } {}
    const std::string& text() const { return m_text; }

    void insert(std::size_t pos, const std::string& s)
    {
        if (s.empty()) return;
        pos = std::min(pos, m_text.size());
        m_text.insert(pos, s);
        if (canMerge(pos, s))
        {
            m_undo.back().inserted += s;
        }
        else
        {
            push({ pos, "", s });
            m_groupOpen = true;
        }
    }

    void erase(std::size_t pos, std::size_t count)
    {
        pos = std::min(pos, m_text.size());
        count = std::min(count, m_text.size() - pos);
        if (count == 0) return;
        const std::string removed{ m_text.substr(pos, count) };
        m_text.erase(pos, count);
        push({ pos, removed, "" });
    }

    void replace(std::size_t pos, std::size_t count, const std::string& s)
    {
        pos = std::min(pos, m_text.size());
        count = std::min(count, m_text.size() - pos);
        const std::string removed{ m_text.substr(pos, count) };
        if (removed == s) return;
        m_text.replace(pos, count, s);
        push({ pos, removed, s });
    }

    void breakGroup() { m_groupOpen = false; }

    bool undo()
    {
        m_groupOpen = false;
        if (m_undo.empty()) return false;
        Step s{ m_undo.back() };
        m_undo.pop_back();
        m_text.replace(s.pos, s.inserted.size(), s.removed);
        m_redo.push_back(s);
        --m_position;
        return true;
    }

    bool redo()
    {
        m_groupOpen = false;
        if (m_redo.empty()) return false;
        Step s{ m_redo.back() };
        m_redo.pop_back();
        m_text.replace(s.pos, s.removed.size(), s.inserted);
        m_undo.push_back(s);
        ++m_position;
        return true;
    }

    bool modified() const { return m_position != m_saved; }
    void markSaved() { m_saved = m_position; m_groupOpen = false; }

    LineCol lineCol(std::size_t pos) const
    {
        pos = std::min(pos, m_text.size());
        int line{ 1 };
        std::size_t start{ 0 };
        for (std::size_t i{ 0 }; i < pos; ++i) if (m_text[i] == '\n') { ++line; start = i + 1; }
        return { line, static_cast<int>(pos - start) + 1 };
    }

    std::size_t offsetOf(int line, int col) const
    {
        std::vector<std::size_t> starts{ 0 };
        for (std::size_t i{ 0 }; i < m_text.size(); ++i) if (m_text[i] == '\n') starts.push_back(i + 1);
        const int l{ std::clamp(line, 1, static_cast<int>(starts.size())) };
        const std::size_t start{ starts[static_cast<std::size_t>(l - 1)] };
        const std::size_t end{ static_cast<std::size_t>(l) < starts.size() ? starts[static_cast<std::size_t>(l)] - 1 : m_text.size() };
        const int c{ std::clamp(col, 1, static_cast<int>(end - start) + 1) };
        return start + static_cast<std::size_t>(c - 1);
    }

    std::optional<std::size_t> find(const std::string& what, std::size_t from, bool matchCase, bool wrap) const
    {
        if (what.empty()) return std::nullopt;
        if (auto at{ search(what, std::min(from, m_text.size()), matchCase) }) return at;
        if (wrap) return search(what, 0, matchCase);
        return std::nullopt;
    }

    int replaceAll(const std::string& what, const std::string& with, bool matchCase)
    {
        if (what.empty()) return 0;
        std::string result;
        std::size_t pos{ 0 };
        int count{ 0 };
        while (auto at{ search(what, pos, matchCase) })
        {
            result += m_text.substr(pos, *at - pos) + with;
            pos = *at + what.size();
            ++count;
        }
        if (count == 0) return 0;
        result += m_text.substr(pos);
        const std::string old{ m_text };
        m_text = result;
        push({ 0, old, result });
        return count;
    }

private:
    struct Step { std::size_t pos; std::string removed; std::string inserted; };

    void push(Step s)
    {
        if (m_saved > m_position) m_saved = -1;            // the saved state can no longer be reached by redo
        m_undo.push_back(std::move(s));
        m_redo.clear();
        ++m_position;
        m_groupOpen = false;
    }

    bool canMerge(std::size_t pos, const std::string& s) const
    {
        if (!m_groupOpen || m_undo.empty() || s.size() != 1 || s == "\n") return false;
        const Step& last{ m_undo.back() };
        if (!last.removed.empty() || pos != last.pos + last.inserted.size()) return false;
        if (last.inserted.back() == '\n') return false;
        if (last.inserted.back() == ' ' && s != " ") return false;
        return true;
    }

    std::optional<std::size_t> search(const std::string& what, std::size_t from, bool matchCase) const
    {
        auto eq = [matchCase](char a, char b) {
            return matchCase ? a == b : std::tolower(static_cast<unsigned char>(a)) == std::tolower(static_cast<unsigned char>(b));
        };
        const auto it{ std::search(m_text.begin() + static_cast<std::ptrdiff_t>(from), m_text.end(), what.begin(), what.end(), eq) };
        if (it == m_text.end()) return std::nullopt;
        return static_cast<std::size_t>(it - m_text.begin());
    }

    std::string m_text;
    std::vector<Step> m_undo, m_redo;
    long m_position{ 0 }, m_saved{ 0 };
    bool m_groupOpen{ false };
};

unitTests:
void type(TextDocument& d, std::size_t pos, const std::string& s) { for (char c : s) d.insert(pos++, std::string(1, c)); }
TEST("typing groups into words") {
    TextDocument d; type(d, 0, "hello world"); CHECK_EQ(d.text(), std::string("hello world"));
    CHECK(d.undo()); CHECK_EQ(d.text(), std::string("hello ")); CHECK(d.undo()); CHECK_EQ(d.text(), std::string("")); CHECK(!d.undo());
    CHECK(d.redo()); CHECK_EQ(d.text(), std::string("hello ")); CHECK(d.redo()); CHECK(!d.redo()); CHECK_EQ(d.text(), std::string("hello world"));
}
TEST("new lines and jumps start new steps") {
    TextDocument d; type(d, 0, "a\nb"); d.undo(); CHECK_EQ(d.text(), std::string("a\n")); d.undo(); CHECK_EQ(d.text(), std::string("a"));
    TextDocument e; type(e, 0, "ab"); e.breakGroup(); type(e, 2, "c"); e.undo(); CHECK_EQ(e.text(), std::string("ab"));
    TextDocument f; type(f, 0, "abc"); type(f, 0, "x"); CHECK_EQ(f.text(), std::string("xabc")); f.undo(); CHECK_EQ(f.text(), std::string("abc"));
}
TEST("erase, replace and redo clearing") {
    TextDocument d{ "hello world" }; d.erase(5, 99); CHECK_EQ(d.text(), std::string("hello")); d.undo(); CHECK_EQ(d.text(), std::string("hello world"));
    d.replace(0, 5, "Howdy"); CHECK_EQ(d.text(), std::string("Howdy world")); d.undo(); CHECK_EQ(d.text(), std::string("hello world"));
    d.insert(999, "!"); CHECK_EQ(d.text(), std::string("hello world!")); CHECK(!d.redo()); d.erase(50, 2); d.undo(); CHECK_EQ(d.text(), std::string("hello world"));
}
TEST("modified") {
    TextDocument d{ "x" }; CHECK(!d.modified()); type(d, 1, "ab"); CHECK(d.modified()); d.markSaved(); CHECK(!d.modified());
    type(d, 3, "c"); CHECK(d.modified()); d.undo(); CHECK(!d.modified()); d.undo(); CHECK(d.modified()); d.redo(); CHECK(!d.modified());
    d.undo(); d.insert(0, "z"); CHECK(d.modified()); d.undo(); CHECK(d.modified());
}
TEST("lines and columns") {
    const TextDocument d{ "ab\ncd\n\nef" };
    CHECK_EQ(d.lineCol(0).line, 1); CHECK_EQ(d.lineCol(2).col, 3); CHECK_EQ(d.lineCol(3).line, 2); CHECK_EQ(d.lineCol(3).col, 1);
    CHECK_EQ(d.lineCol(6).line, 3); CHECK_EQ(d.lineCol(7).line, 4); CHECK_EQ(d.lineCol(9).col, 3);
    CHECK_EQ(d.offsetOf(2, 2), std::size_t{ 4 }); CHECK_EQ(d.offsetOf(2, 99), std::size_t{ 5 }); CHECK_EQ(d.offsetOf(99, 1), std::size_t{ 7 }); CHECK_EQ(d.offsetOf(0, 0), std::size_t{ 0 }); CHECK_EQ(d.offsetOf(3, 5), std::size_t{ 6 });
}
TEST("find") {
    const TextDocument d{ "One two one TWO" };
    CHECK_EQ(*d.find("one", 0, false, false), std::size_t{ 0 }); CHECK_EQ(*d.find("one", 1, false, false), std::size_t{ 8 }); CHECK_EQ(*d.find("One", 1, true, true), std::size_t{ 0 });
    CHECK_EQ(*d.find("two", 12, false, false), std::size_t{ 12 }); CHECK(!d.find("two", 13, false, false)); CHECK_EQ(*d.find("two", 13, false, true), std::size_t{ 4 });
    CHECK_EQ(*d.find("TWO", 0, true, false), std::size_t{ 12 }); CHECK(!d.find("", 0, false, true)); CHECK(!d.find("three", 0, false, true));
}
TEST("replace all is one step") {
    TextDocument d{ "One two one TWO" }; CHECK_EQ(d.replaceAll("one", "1", false), 2); CHECK_EQ(d.text(), std::string("1 two 1 TWO"));
    CHECK_EQ(d.replaceAll("xyz", "-", false), 0); d.undo(); CHECK_EQ(d.text(), std::string("One two one TWO")); CHECK(!d.undo());
    TextDocument e{ "aaaa" }; CHECK_EQ(e.replaceAll("aa", "b", true), 2); CHECK_EQ(e.text(), std::string("bb"));
}

